import{_ as a,o,c as t,a2 as r}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/pt/planejadores-detalhe.png",n="/pro-agent-hub-installer/capturas/pt/planejadores-execucao.png",h=JSON.parse('{"title":"Planejadores","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/planejadores.md","filePath":"pt/interface/planejadores.md","lastUpdated":1787856241000}'),d={name:"pt/interface/planejadores.md"};function i(l,e,c,u,p,m){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="planejadores" tabindex="-1">Planejadores <a class="header-anchor" href="#planejadores" aria-label="Permalink to &quot;Planejadores&quot;">​</a></h1><p>Um <strong>workflow</strong> sabe o caminho de antemão; você desenhou cada passo. Um <strong>planejador</strong> não: você dá o objetivo e ele descobre o caminho, um passo por vez.</p><p>O ciclo é sempre o mesmo — <strong>planejar → agir → observar → avaliar → replanejar</strong> — e ele repete até cumprir o critério de sucesso ou bater num limite.</p><p>Use planejador quando os passos dependem do que for encontrado no caminho. Quando você já sabe a sequência, workflow é mais barato, mais rápido e mais previsível.</p><h2 id="aba-geral" tabindex="-1">Aba Geral <a class="header-anchor" href="#aba-geral" aria-label="Permalink to &quot;Aba Geral&quot;">​</a></h2><p><img src="'+s+'" alt="planejadores-detalhe"></p><p><strong>Objetivo</strong> é o que se quer alcançar. Ele fica gravado como padrão e pode ser substituído a cada disparo — pela tela de execução, por um workflow ou pela API.</p><p><strong>Critério de sucesso</strong> é o texto que o modelo avalia ao fim de cada volta para decidir se já chegou. Sem ele, o planejador só para nos limites, e vai gastar todas as iterações que puder. Escreva algo verificável: &quot;o arquivo foi gravado e a resposta contém o total apurado&quot; funciona; &quot;resolver bem&quot; não.</p><p><strong>Modelo</strong> é quem planeja e avalia — não é quem executa. Vale investir num modelo melhor aqui do que nos executores: um plano ruim desperdiça todas as voltas seguintes.</p><p><strong>Agente base</strong> (opcional) é quem faz as ações diretas. Definindo um, o planejador herda os MCPs, conhecimentos e ferramentas que aquele agente já tem. Sem ele, as ações diretas usam um agente efêmero, sem nada vinculado.</p><h3 id="executores" tabindex="-1">Executores <a class="header-anchor" href="#executores" aria-label="Permalink to &quot;Executores&quot;">​</a></h3><p>Ainda na aba Geral: os agentes e times que o planejador pode acionar. <strong>Esta lista é o que o modelo enxerga na hora de montar o plano</strong> — ele só delega um passo a quem estiver aqui.</p><p>Cada vínculo carrega uma descrição do que aquele executor faz. Escreva-a pensando em quem lê: quem escolhe é o modelo, com base nesse texto.</p><h3 id="limites" tabindex="-1">Limites <a class="header-anchor" href="#limites" aria-label="Permalink to &quot;Limites&quot;">​</a></h3><p>Fecham a aba Geral. São quatro tetos, todos verificados <strong>entre passos</strong> — nunca no meio de um:</p><table tabindex="0"><thead><tr><th>Limite</th><th>Padrão</th><th>Para que serve</th></tr></thead><tbody><tr><td>Iterações</td><td>15</td><td>Quantas voltas do ciclo.</td></tr><tr><td>Passos</td><td>50</td><td>Quantas ações no total, somando todas as voltas.</td></tr><tr><td>Tokens</td><td>—</td><td>Orçamento de tokens da execução. Sem valor, sem teto.</td></tr><tr><td>Tempo</td><td>900 s</td><td>Duração máxima.</td></tr></tbody></table><p>Estes limites não são detalhe de configuração: um planejador é um laço guiado por um modelo, e o modelo pode não convergir. São eles que garantem que a execução termina.</p><h2 id="aba-ferramentas" tabindex="-1">Aba Ferramentas <a class="header-anchor" href="#aba-ferramentas" aria-label="Permalink to &quot;Aba Ferramentas&quot;">​</a></h2><p>Quais operações internas o loop pode chamar, e quais conexões de banco ele pode tocar.</p><div class="warning custom-block"><p class="custom-block-title">Sem fonte de dados liberada, as funções de banco são recusadas</p><p><code>db_query</code>, <code>db_insert</code>, <code>db_update</code>, <code>db_delete</code> e <code>db_upsert</code> são bloqueadas <strong>antes de executar</strong> quando nenhuma conexão está liberada. Isso é deliberado: sem uma lista, o modelo teria de adivinhar o ID da conexão, e adivinhar certo seria acesso a uma base que o planejador não deveria tocar.</p></div><p>A lista de ferramentas disponíveis está em <a href="/pro-agent-hub-installer/pt/funcoes/planejador">Planejador</a>.</p><h2 id="abas-executar-e-execucoes" tabindex="-1">Abas Executar e Execuções <a class="header-anchor" href="#abas-executar-e-execucoes" aria-label="Permalink to &quot;Abas Executar e Execuções&quot;">​</a></h2><p><img src="'+n+'" alt="planejadores-execucao"></p><p>Em <strong>Executar</strong> você dispara o planejador, opcionalmente trocando o objetivo. A tela acompanha ao vivo: o plano montado, cada passo com o executor escolhido, o que foi observado e a avaliação da volta. Tudo fica gravado, e a aba <strong>Execuções</strong> guarda o histórico — é possível reabrir uma execução antiga e ler o raciocínio inteiro.</p><p>A execução termina como <strong>concluída</strong>, <strong>falha</strong>, <strong>cancelada</strong> ou por <strong>limite atingido</strong> — e, neste último caso, qual limite. Se um planejador vive batendo em <code>max_iterations</code>, o problema quase nunca é o teto: é o critério de sucesso ou a descrição dos executores.</p>',25)])])}const g=a(d,[["render",i]]);export{h as __pageData,g as default};
